<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\{Booking,ChampionshipAgeCategory,ChampionshipDraw,ChampionshipEntry,ChampionshipEvent,ChampionshipMatch,ClubChampionship,Facility,Member,SportMembership};use Carbon\Carbon;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class ChampionshipController extends Controller {
 public function index(){return response()->json(['championships'=>ClubChampionship::with(['events.ageCategory','events.entries.members','events.draws.matches.entry1.members','events.draws.matches.entry2.members'])->latest()->get(),'categories'=>ChampionshipAgeCategory::orderBy('minimum_age')->get(),'members'=>Member::orderBy('last_name')->orderBy('first_name')->get(['id','first_name','last_name','preferred_name','date_of_birth','gender']),'facilities'=>Facility::where('active',true)->orderBy('name')->get(['id','name'])]);}
 public function store(Request $r){$d=$r->validate(['name'=>'required|max:255','season'=>'nullable|max:50','starts_on'=>'required|date','ends_on'=>'required|date|after_or_equal:starts_on','age_cutoff_on'=>'required|date','entries_open_at'=>'nullable|date','entries_close_at'=>'nullable|date','regulations'=>'nullable|string']);$d['convenor_user_id']=$r->user()->id;return response()->json(ClubChampionship::create($d),201);}
 public function deleteChampionship(ClubChampionship $championship){$hasActivity=$championship->events()->where(function($query){$query->whereHas('entries')->orWhereHas('draws');})->exists();if($hasActivity)throw ValidationException::withMessages(['championship'=>'Championships with entries or draws must be archived instead of deleted.']);$championship->delete();return response()->noContent();}
 public function category(Request $r){return response()->json(ChampionshipAgeCategory::create($r->validate(['name'=>'required|max:100','minimum_age'=>'nullable|integer|min:0','maximum_age'=>'nullable|integer|min:0','combined_minimum_age'=>'nullable|integer|min:0','team_age_rule'=>'required|in:both,youngest,oldest'])),201);}
 public function deleteCategory(ChampionshipAgeCategory $category){$standard=['Open','Under 10','Under 12','Under 14','Under 16','Under 18','30+','35+','40+','45+','50+','55+','60+','65+'];if(in_array($category->name,$standard,true))throw ValidationException::withMessages(['category'=>'Standard championship categories cannot be deleted.']);if(ChampionshipEvent::where('age_category_id',$category->id)->exists())throw ValidationException::withMessages(['category'=>'This category is used by an event and cannot be deleted.']);$category->delete();return response()->noContent();}
 public function event(Request $r,ClubChampionship $championship){$d=$r->validate(['name'=>'required|max:255','age_category_id'=>'nullable|exists:championship_age_categories,id','discipline'=>'required|in:singles,doubles','gender_rule'=>'required|in:male,female,mixed,open','draw_format'=>'required|in:knockout,round_robin,group_knockout,consolation,feed_in,compass,monrad,double_elimination,swiss,custom','ranking_rules'=>'nullable|array|max:7','ranking_rules.*'=>'required|distinct|in:matches_won,head_to_head,sets_won,set_percentage,games_won,game_percentage,seed','entry_fee_cents'=>'required|integer|min:0','fee_basis'=>'required|in:player,team','capacity'=>'nullable|integer|min:2','seed_count'=>'required|integer|min:0']);$d['ranking_rules']=$d['ranking_rules']??['matches_won','head_to_head','sets_won','game_percentage'];return response()->json($championship->events()->create($d),201);}
 public function updateEvent(Request $r,ChampionshipEvent $event){$d=$r->validate(['name'=>'required|max:255','age_category_id'=>'nullable|exists:championship_age_categories,id','discipline'=>'required|in:singles,doubles','gender_rule'=>'required|in:male,female,mixed,open','draw_format'=>'required|in:knockout,round_robin,group_knockout,consolation,feed_in,compass,monrad,double_elimination,swiss,custom','ranking_rules'=>'nullable|array|max:7','ranking_rules.*'=>'required|distinct|in:matches_won,head_to_head,sets_won,set_percentage,games_won,game_percentage,seed','entry_fee_cents'=>'required|integer|min:0','fee_basis'=>'required|in:player,team','capacity'=>'nullable|integer|min:2','seed_count'=>'required|integer|min:0']);if(($d['draw_format']!==$event->draw_format||$d['discipline']!==$event->discipline)&&$event->draws()->exists())throw ValidationException::withMessages(['event'=>'Delete the draft draw before changing the discipline or draw format.']);$d['ranking_rules']=$d['ranking_rules']??[];$event->update($d);return response()->json($event->fresh('ageCategory'));}
 public function archiveEvent(ChampionshipEvent $event){$event->update(['status'=>'archived']);return $event;}
 public function deleteEvent(ChampionshipEvent $event){if($event->entries()->exists()||$event->draws()->exists())throw ValidationException::withMessages(['event'=>'Events with entries or draws must be archived instead of deleted.']);$event->delete();return response()->noContent();}
 public function entry(Request $r,ChampionshipEvent $event){
  $d=$r->validate(['member_ids'=>'required|array|min:1|max:128','member_ids.*'=>'distinct|exists:members,id']);
  $membersById=Member::whereIn('id',$d['member_ids'])->get()->keyBy('id');
  $members=collect($d['member_ids'])->map(fn($id)=>$membersById->get($id));
  if($event->discipline==='doubles'&&$members->count()!==2)throw ValidationException::withMessages(['member_ids'=>'A doubles entry requires exactly two members.']);
  $duplicate=$event->entries()->whereHas('members',fn($query)=>$query->whereIn('members.id',$members->pluck('id')))->exists();
  if($duplicate)throw ValidationException::withMessages(['member_ids'=>'One or more selected members are already entered in this event.']);
  $snapshots=[];
  foreach($members as $m){
   $active=SportMembership::where('member_id',$m->id)->where('status','active')->whereDate('starts_on','<=',$event->championship->starts_on)->whereDate('ends_on','>=',$event->championship->starts_on)->exists();
   if(!$active)throw ValidationException::withMessages(['member_ids'=>"{$m->display_name} has no active membership."]);
   $age=Carbon::parse($m->date_of_birth)->diffInYears($event->championship->age_cutoff_on);
   $snapshots[$m->id]=['member_id'=>$m->id,'age'=>$age,'gender'=>$m->gender];
  }
  $cat=$event->ageCategory;
  if($cat&&collect($snapshots)->contains(fn($s)=>($cat->minimum_age!==null&&$s['age']<$cat->minimum_age)||($cat->maximum_age!==null&&$s['age']>$cat->maximum_age)))throw ValidationException::withMessages(['member_ids'=>'Age category requirements are not met.']);
  if($event->gender_rule==='mixed'&&($event->discipline!=='doubles'||$members->pluck('gender')->unique()->count()!==2))throw ValidationException::withMessages(['member_ids'=>'Mixed doubles requires one male and one female member.']);
  $entries=DB::transaction(function()use($event,$members,$snapshots){
   $groups=$event->discipline==='singles'?$members->map(fn($member)=>collect([$member])):collect([$members]);
   return $groups->map(function($entrants)use($event,$snapshots){
    $fee=$event->entry_fee_cents*($event->fee_basis==='player'?$entrants->count():1);
    $snap=$entrants->map(fn($member)=>$snapshots[$member->id])->values()->all();
    $entry=$event->entries()->create(['status'=>'pending','payment_status'=>$fee?'pending':'not_required','fee_cents'=>$fee,'eligibility_snapshot'=>$snap]);
    foreach($entrants->values() as $i=>$member)$entry->members()->attach($member->id,['position'=>$i+1,'confirmation_status'=>'confirmed']);
    return $entry->load('members');
   });
  });
  return response()->json(['entries'=>$entries],201);
 }
 public function review(Request $r,ChampionshipEntry $entry){$entry->update($r->validate(['status'=>'required|in:pending,accepted,waitlisted,rejected,withdrawn','payment_status'=>'required|in:pending,paid,waived,refunded','seed'=>'nullable|integer|min:1','override_reason'=>'nullable|string'])+['reviewed_by_user_id'=>$r->user()->id]);return $entry->load('members');}
 public function draw(ChampionshipEvent $event){
  $payableStatuses=['paid','waived','not_required'];
  $entries=$event->entries()->whereIn('status',['pending','accepted'])->whereIn('payment_status',$payableStatuses)->orderByRaw('seed is null, seed')->get();
  if($entries->count()<2)throw ValidationException::withMessages(['draw'=>'At least two paid, waived, or no-fee entries are required.']);
  if($event->draw_format==='group_knockout'&&$entries->count()<4)throw ValidationException::withMessages(['draw'=>'Round robin to elimination requires at least four eligible entries.']);
  $draw=DB::transaction(function()use($event,$entries){
   $event->entries()->whereIn('id',$entries->pluck('id'))->where('status','pending')->update(['status'=>'accepted']);
   $draw=$event->draws()->create(['version'=>(int)$event->draws()->lockForUpdate()->max('version')+1,'format'=>$event->draw_format,'settings'=>['ranking_rules'=>$event->ranking_rules?:['matches_won','head_to_head','sets_won','game_percentage']]]);
   if(in_array($event->draw_format,['round_robin','swiss'],true))$this->createRoundRobinDraw($draw,$entries);
   elseif($event->draw_format==='group_knockout')$this->createGroupKnockoutDraw($draw,$entries);
   else $this->createKnockoutDraw($draw,$entries,$event->draw_format==='consolation');
   return $draw;
  });
  return response()->json($draw->load('matches.entry1.members','matches.entry2.members'),201);
 }

 private function createGroupKnockoutDraw(ChampionshipDraw $draw,$entries):void{$groupCount=2;while((int)ceil($entries->count()/$groupCount)>4)$groupCount*=2;$groups=array_fill(0,$groupCount,[]);foreach($entries->values() as $index=>$entry){$cycle=intdiv($index,$groupCount);$position=$index%$groupCount;$groupIndex=$cycle%2===0?$position:$groupCount-1-$position;$groups[$groupIndex][]=$entry;}$matchNumber=1;foreach($groups as $groupIndex=>$group){$groupName='Group '.chr(65+$groupIndex);for($i=0;$i<count($group);$i++)for($j=$i+1;$j<count($group);$j++)$draw->matches()->create(['stage'=>'group','round_number'=>1,'round_name'=>$groupName,'match_number'=>$matchNumber++,'entry1_id'=>$group[$i]->id,'entry2_id'=>$group[$j]->id,'status'=>'ready_to_schedule']);}$qualifiers=$groupCount*2;$rounds=(int)log($qualifiers,2);$previous=[];for($round=1;$round<=$rounds;$round++){$count=$qualifiers/(2**$round);$current=[];for($match=1;$match<=$count;$match++){$firstRound=$round===1;$pairStart=intdiv($match-1,2)*2;$odd=$match%2===1;$source1=$firstRound?'Group '.chr(65+($odd?$pairStart:$pairStart+1)).' #1':'winner';$source2=$firstRound?'Group '.chr(65+($odd?$pairStart+1:$pairStart)).' #2':'winner';$item=$draw->matches()->create(['stage'=>'elimination','round_number'=>$round,'round_name'=>$count===1?'Final':($count===2?'Semi-finals':($count===4?'Quarter-finals':'Round of '.($count*2))),'match_number'=>$match,'source1_match_id'=>$firstRound?null:$previous[($match-1)*2]->id,'source2_match_id'=>$firstRound?null:$previous[($match-1)*2+1]->id,'source1_outcome'=>$source1,'source2_outcome'=>$source2,'status'=>'pending_players']);$current[]=$item;}$previous=$current;}$draw->update(['settings'=>array_merge($draw->settings??[],['group_count'=>$groupCount,'qualifiers_per_group'=>2])]);}

 private function createRoundRobinDraw(ChampionshipDraw $draw,$entries):void{$number=1;for($i=0;$i<$entries->count();$i++)for($j=$i+1;$j<$entries->count();$j++)$draw->matches()->create(['stage'=>'group','round_number'=>1,'round_name'=>'Round robin','match_number'=>$number++,'entry1_id'=>$entries[$i]->id,'entry2_id'=>$entries[$j]->id,'status'=>'ready_to_schedule']);$draw->update(['settings'=>array_merge($draw->settings??[],['qualifiers_per_group'=>0])]);}

 private function createKnockoutDraw(ChampionshipDraw $draw,$entries,bool $withConsolation=false):void{$size=2;while($size<$entries->count())$size*=2;$slots=array_fill(0,$size,null);$ordered=$entries->values();if($ordered->isNotEmpty())$slots[0]=$ordered->shift();$end=$size-1;if($ordered->isNotEmpty())$slots[$end]=$ordered->shift();$cursor=1;foreach($ordered as $entry){while($slots[$cursor])$cursor++;$slots[$cursor++]=$entry;}$previous=[];$allRounds=[];$rounds=(int)log($size,2);for($round=1;$round<=$rounds;$round++){$count=$size/(2**$round);$current=[];for($match=1;$match<=$count;$match++){$item=$draw->matches()->create(['round_number'=>$round,'round_name'=>$count===1?'Final':($count===2?'Semi-finals':($count===4?'Quarter-finals':'Round of '.($count*2))),'match_number'=>$match,'entry1_id'=>$round===1?optional($slots[($match-1)*2])->id:null,'entry2_id'=>$round===1?optional($slots[($match-1)*2+1])->id:null,'source1_match_id'=>$round>1?$previous[($match-1)*2]->id:null,'source2_match_id'=>$round>1?$previous[($match-1)*2+1]->id:null,'source1_outcome'=>$round>1?'winner':null,'source2_outcome'=>$round>1?'winner':null,'status'=>$round===1?'ready_to_schedule':'pending_players']);$current[]=$item;}$allRounds[]=$current;$previous=$current;}foreach($allRounds[0] as $first){if((bool)$first->entry1_id===(bool)$first->entry2_id){$winner=$first->entry1_id?:$first->entry2_id;$first->update(['winner_entry_id'=>$winner,'status'=>'completed','result_type'=>'bye','result_status'=>'verified','completed_at'=>now()]);foreach($allRounds[1]??[] as $next){if($next->source1_match_id===$first->id)$next->update(['entry1_id'=>$winner]);if($next->source2_match_id===$first->id)$next->update(['entry2_id'=>$winner]);if($next->entry1_id&&$next->entry2_id)$next->update(['status'=>'ready_to_schedule']);}}}if($withConsolation){$sources=collect($allRounds[0])->filter(fn($m)=>$m->entry1_id&&$m->entry2_id)->values();$round=1;while($sources->count()>1){$count=(int)ceil($sources->count()/2);$current=collect();for($i=0;$i<$count;$i++){$a=$sources->get($i*2);$b=$sources->get($i*2+1);$current->push($draw->matches()->create(['stage'=>'consolation','round_number'=>$round,'round_name'=>$count===1?'Consolation final':'Consolation round '.$round,'match_number'=>$i+1,'source1_match_id'=>$a?->id,'source2_match_id'=>$b?->id,'source1_outcome'=>$round===1?'loser':'winner','source2_outcome'=>$round===1?'loser':'winner','status'=>'pending_players']));}$sources=$current;$round++;}}}
 public function publish(ChampionshipDraw $draw){$draw->update(['status'=>'published','published_at'=>now()]);$draw->championshipEvent?->championship?->update(['status'=>'draw_published']);return $draw;}
 public function deleteDraw(ChampionshipDraw $draw){if($draw->status!=='draft')throw ValidationException::withMessages(['draw'=>'Published draws cannot be deleted.']);$draw->delete();return response()->noContent();}
 public function status(Request $r,ClubChampionship $championship){$championship->update($r->validate(['status'=>'required|in:draft,entries_open,entries_closed,draw_published,in_progress,completed,archived']));return $championship;}
}
